WITH e AS (SELECT * FROM json_to_recordset($1::json) AS q(stay_id integer,subject_id integer,hadm_id integer,time_zero timestamp)) SELECT e.stay_id,s.drug_class,MAX(s.rate) AS rate FROM e JOIN analysis._tmp_sedative_raw s ON s.stay_id=e.stay_id AND s.infusion_start<=e.time_zero AND s.infusion_end>e.time_zero WHERE (s.drug_class='propofol' AND s.rateuom='mcg/kg/min') OR (s.drug_class='midazolam' AND s.rateuom='mg/hour') OR (s.drug_class='dexmedetomidine' AND s.rateuom='mcg/kg/hour') GROUP BY e.stay_id,s.drug_class;
